function afr_json($v,$s=200){http_response_code($s);echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function afr_error($m,$s=400){afr_json(['error'=>$m],$s);}function afr_auth(){global $CONFIG;$tok=Http::bearer();$p=$tok?Jwt::verify($tok,$CONFIG['jwt_secret']):null;if(!$p||empty($p['sub']))afr_error('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.is_active,u.is_admin,r.level,r.title role_title FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? LIMIT 1",[$p['sub']]);if(!$u||!(int)$u['is_active'])afr_error('کاربر نامعتبر',401);$dt=$p['dt']??'web';$sess=Db::one("SELECT device_id,revoked_at FROM user_sessions WHERE user_id=? AND device_type=? ORDER BY id DESC LIMIT 1",[$u['id'],$dt]);$unlimited=in_array($u['role_title'],['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true);if(!$sess||$sess['revoked_at']||(!$unlimited&&$sess['device_id']!==($p['device_id']??'')))afr_error('نشست منقضی یا باطل شده است',401);if(empty($u['is_admin']))afr_error('دسترسی مدیریتی لازم است',403);return$u;}
function afr_en($s){return strtr((string)$s,['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);}
function afr_j2g($jy,$jm,$jd){$jy=(int)$jy-979;$jm=(int)$jm-1;$jd=(int)$jd-1;$jdn=365*$jy+intdiv($jy,33)*8+intdiv(($jy%33+3),4);$md=[31,31,31,31,31,31,30,30,30,30,30,29];for($i=0;$i<$jm;$i++)$jdn+=$md[$i];$jdn+=$jd;$g=$jdn+79;$gy=1600+400*intdiv($g,146097);$g%=146097;$leap=true;if($g>=36525){$g--; $gy+=100*intdiv($g,36524);$g%=36524;if($g>=365)$g++;else$leap=false;}$gy+=4*intdiv($g,1461);$g%=1461;if($g>=366){$leap=false;$g--; $gy+=intdiv($g,365);$g%=365;}$gd=[31,($leap?29:28),31,30,31,30,31,31,30,31,30,31];$gm=0;for(;$gm<12&&$g>=$gd[$gm];$gm++)$g-=$gd[$gm];return[$gy,$gm+1,$g+1];}
function afr_g2j($gy,$gm,$gd){$gdm=[0,31,59,90,120,151,181,212,243,273,304,334];$gy2=$gy-1600;$gm2=$gm-1;$gd2=$gd-1;$gdn=365*$gy2+intdiv($gy2+3,4)-intdiv($gy2+99,100)+intdiv($gy2+399,400)+$gdm[$gm2]+$gd2;if($gm2>1&&(($gy%4==0&&$gy%100!=0)||($gy%400==0)))$gdn++;$jdn=$gdn-79;$jy=979+33*intdiv($jdn,12053);$jdn%=12053;$jy+=4*intdiv($jdn,1461);$jdn%=1461;if($jdn>=366){$jy+=intdiv($jdn-1,365);$jdn=($jdn-1)%365;}$jm=$jdn<186?1+intdiv($jdn,31):7+intdiv($jdn-186,30);$jd=1+($jdn<186?$jdn%31:($jdn-186)%30);return[$jy,$jm,$jd];}
function afr_jts($j){$j=preg_replace('/[\/-]/','-',afr_en(trim((string)$j)));if(!preg_match('/^(\d{4})-(\d{1,2})-(\d{1,2})$/',$j,$m))return null;[$gy,$gm,$gd]=afr_j2g($m[1],$m[2],$m[3]);return mktime(0,0,0,$gm,$gd,$gy);}
function afr_jdate($ts){[$jy,$jm,$jd]=afr_g2j((int)date('Y',$ts),(int)date('n',$ts),(int)date('j',$ts));return sprintf('%04d-%02d-%02d',$jy,$jm,$jd);}
function afr_hm($m){$m=max(0,(int)$m);return sprintf('%02d:%02d',intdiv($m,60),$m%60);}
function afr_shift_cache($uid){$rows=Db::all("SELECT us.user_id,us.shift_id,us.from_jdate,us.to_jdate,s.* FROM user_shifts us JOIN shifts s ON s.id=us.shift_id WHERE us.user_id=? AND s.is_active=1",[$uid]);$out=[];foreach($rows as $r)$out[]=['row'=>$r,'from'=>!empty($r['from_jdate'])?str_replace('/','-',$r['from_jdate']):null,'to'=>!empty($r['to_jdate'])?str_replace('/','-',$r['to_jdate']):null];return$out;}
function afr_shift_for($uid,$jdate,&$cache){foreach($cache as $x){if($x['from']&&strcmp($jdate,$x['from'])<0)continue;if($x['to']&&strcmp($jdate,$x['to'])>0)continue;return$x['row'];}static$auto=[];if(!array_key_exists($uid,$auto))$auto[$uid]=_auto_shift_for_user($uid);return$auto[$uid];}
function afr_shift_days_map($cache,$from,$to){$ids=[];foreach($cache as $x){$id=(int)($x['row']['shift_id']??$x['row']['id']??0);if($id)$ids[$id]=1;}if(!$ids)return[];$ph=implode(',',array_fill(0,count($ids),'?'));$args=array_keys($ids);$args[]=$from;$args[]=$to;$map=[];try{$rows=Db::all("SELECT shift_id,jdate,segments,is_off,day_config FROM shift_days WHERE shift_id IN ($ph) AND REPLACE(jdate,'/','-')>=? AND REPLACE(jdate,'/','-')<=?",$args);foreach($rows as $r){$j=str_replace('/','-',(string)$r['jdate']);$map[(int)$r['shift_id']][$j]=$r;}}catch(Throwable $e){}return$map;}
function afr_table_exists($table){static$c=[];if(array_key_exists($table,$c))return$c[$table];try{$r=Db::one("SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1",[$table]);}catch(Throwable$e){$r=null;}return$c[$table]=($r!==null);}
function afr_adjusted_map($uid,$from,$to){if(!afr_table_exists('attendance_ot_adjustments'))return[];$out=[];try{$rows=Db::all("SELECT jdate,minutes FROM attendance_ot_adjustments WHERE user_id=? AND REPLACE(jdate,'/','-')>=? AND REPLACE(jdate,'/','-')<=?",[$uid,$from,$to]);foreach($rows as $r)$out[str_replace('/','-',(string)$r['jdate'])]=(int)($r['minutes']??0);}catch(Throwable$e){}return$out;}
