function afr_approved_requests_map($uid,$from,$to){$out=[];$types=['annual','sick','unpaid','mission'];try{$ph=implode(',',array_fill(0,count($types),'?'));$rows=Db::all("SELECT type,unit,from_jdate,to_jdate,the_date,from_time,to_time,minutes FROM requests WHERE user_id=? AND status='approved' AND type IN ($ph) ORDER BY id",array_merge([$uid],$types));foreach($rows as $r){$type=(string)$r['type'];$f=str_replace('/','-',trim((string)($r['from_jdate']?:$r['the_date'])));$t=str_replace('/','-',trim((string)($r['to_jdate']?:$r['the_date']?:$r['from_jdate'])));if(!$f)$f=$t;if(!$t)$t=$f;$fts=afr_jts($f);$tts=afr_jts($t);if($fts===null||$tts===null||$fts>$tts)continue;if($r['unit']==='hourly'){$a=explode(':',(string)($r['from_time']??'0:0'));$b=explode(':',(string)($r['to_time']??'0:0'));$mins=max(0,((int)($b[0]??0)*60+(int)($b[1]??0))-((int)($a[0]??0)*60+(int)($a[1]??0)));if($mins<=0)$mins=(int)($r['minutes']??0);$key=afr_jdate($fts);if($key>=$from&&$key<=$to)$out[$key][$type]=($out[$key][$type]??0)+$mins;continue;}$days=max(1,(int)(($tts-$fts)/86400)+1);$mins=(int)($r['minutes']??0);if($mins<=0)$mins=$days*480;$perDay=$days>0?intdiv($mins,$days):$mins;for($dts=$fts;$dts<=$tts;$dts+=86400){$key=afr_jdate($dts);if($key<$from||$key>$to)continue;$out[$key][$type]=($out[$key][$type]??0)+$perDay;}}}catch(Throwable $e){error_log('attendance-report-fast approved requests: '.$e->getMessage());}return$out;}
